import { Component, ElementRef, OnInit, ViewChild } from '@angular/core';
import { FormArray, FormBuilder, FormControl, FormGroup } from '@angular/forms';
import { ActivatedRoute, Router } from '@angular/router';
import { UserService } from 'src/app/services/emis/user.service';
import { UserSessionService } from 'src/app/services/usersession.service';

@Component({
  selector: 'app-school-data',
  templateUrl: './school-data.page.html',
  styleUrls: ['./school-data.page.scss'],
})
export class SchoolDataPage implements OnInit {
  headerList: { id: number; header: string; }[];
  form: FormGroup;
  
  sch_id: any;
  school_type: string;
  school_name: string;
  udise_code: any;
  headerType: string = "Header";
  school_id: any;

  constructor(private SchoolsService: UserService,private router: Router,
    private userSessionService: UserSessionService,
    private route: ActivatedRoute,
    private userService: UserService,

    public fb: FormBuilder) {
      this.sch_id = this.router.getCurrentNavigation().extras;
      // this.schoolTypeId = +this.userSessionService.schoolTypeId();
      // this.schoolId = this.userSessionService.schoolId();
    
    }

  ngOnInit() {
    if (this.route.snapshot.queryParamMap.get("id")) {
      // @ts-ignore TS2322
      this.udise_code = this.route.snapshot.queryParamMap.get("id");
      this.school_name = this.route.snapshot.queryParamMap.get("school_name");
      this.school_type = this.route.snapshot.queryParamMap.get("school_type");
      this.school_id = this.route.snapshot.queryParamMap.get("sclid");
     
      // console.log(this.school_name,this.school_type,this.udise_code)
    }

    this.userService.getUdisePdf(this.school_id).subscribe((response) => {
    //  console.log(response,"dataresponse",this.school_id)
    });

    this.getHeadings();
  }

  getHeadings() {
      this.headerList = [
        {
          id: 1,
          header: 'BASIC INFORMATION'
        },
        {
          id: 2,
          header: 'STUDENT AND STAFF DETAILS'
        },
        {
          id: 3,
          header: 'SCHOOL DETAILS'
        }
      ];
  }

  getheaderOpen(headerType){

    if(headerType == 'BASIC INFORMATION') {
      this.headerType = 'BASIC INFORMATION'
    }
    if(headerType == 'STUDENT AND STAFF DETAILS') {
      this.headerType = 'STUDENT AND STAFF DETAILS'
    }
    if(headerType == 'SCHOOL DETAILS') {
      this.headerType = 'SCHOOL DETAILS'
    }

  }

  goToBack(){
    this.headerType = 'Header'
  }

  goToBackMenu(){
    this.router.navigate(['/tabs/nearby-school']);
  }

  initialValidator() {
    this.form = this.fb.group({
      'udise_code': new FormControl('', null),
      'school_name': new FormControl('', null),
      'latitude': new FormControl('', null),
      'longitude': new FormControl('', null),
      
      schoolnew_mediumentry_details: this.fb.array([]),
      schoolnew_langtaught_entry_details: this.fb.array([]),
      voc_trade_details: this.fb.array([]),
            /*newly created fields */
    });
  }


  getMediumInstruction(item) {
    const mediumentry = this.form.controls.schoolnew_mediumentry_details as FormArray;
    for (let i = 0; i < item.length; i++) {
      mediumentry.push(this.fb.group({
        // school_key_id: this.schoolId,
        medium_instrut: item[i].id,
       // other_medium: item[i].other_medium,
        medium: item[i].MEDINSTR_DESC,
      })
      )
    }
  }

  getLanguageList(items) {
    const langtaught_entry = this.form.controls.schoolnew_langtaught_entry_details as FormArray;
    for (let i = 0; i < items.length; i++) {
      langtaught_entry.push(this.fb.group({
        // school_key_id: this.schoolId,
        lang_taught: items[i].id,
        lang: items[i].MEDINSTR_DESC
      })
      )
    }
  }

  getVocationList(data) {
    const vocation_entry = this.form.controls.voc_trade_details as FormArray;
    for (let i = 0; i < data.length; i++) {
      vocation_entry.push(this.fb.group({
        // school_key_id: this.schoolId,
        voc_trade: data[i].voc_trade,
        trade: data[i].trade,
      })
      )
    }
  }

}

  